// Prepared full front and back walk poses, 172 × 144 pixels per cell.
const DAWN_WALK_BITMAPS={
 luffy:'data:image/webp;base64,',
 zoro:'data:image/webp;base64,',
 nami:'data:image/webp;base64,',
};
const DAWN_WALK_IMAGES=Object.fromEntries(Object.entries(DAWN_WALK_BITMAPS).map(([id,data])=>{
 const image=new Image();image.src=data;return [id,image];
}));
const dawnWalkReady=id=>!!DAWN_WALK_IMAGES[id]?.naturalWidth;
function drawDawnWalkFrame(g,id,row,step){
 if((row!==0&&row!==3)||!dawnWalkReady(id))return false;
 g.drawImage(DAWN_WALK_IMAGES[id],step*172,row===3?144:0,172,144,0,0,172,144);
 return true;
}
